exercise.question:
\mpBR{7.5cm}{
Berechnen Sie in der nebenstehenden Schaltung die Spannung $U$. 

}
{

\psTdC{Iq1}{$I_\mathrm{q1}$}
\psTdC{Iq2}{$I_\mathrm{q2}$}
\psMsC{U}
\psMsL{R}
\psTdL{R1}{$R_1$}
\psTdL{R2}{$R_2$}

![Abbildung zur Aufgabe et1-03-014-ueberlagerungssatz-4: Ueberlagerungssatz 4](assets/et1-03-014-ueberlagerungssatz-4/01-Ueberlagerungssatz_4.png)

}

exercise.solution_path:
\begin{align*}
U&=U_{I_\mathrm{q1}}+U_{I_\mathrm{q2}}

U_{I_\mathrm{q1}}&=R I_\mathrm{q1}\cdot \dfrac{R_1}{R_1+R_2+R||(R_1+R_2)} \cdot \dfrac{R_1 + R_2}{R + R_1 + R_2}

&= R I_\mathrm{q1} \cdot \dfrac{R_1}{R_1+R_2+\dfrac{R(R_1 + R_2)}{R + R_1 + R_2}} \cdot \dfrac{R_1 + R_2}{R + R_1 + R_2}

U_{I_\mathrm{q1}}&=I_\mathrm{q1}\cdot \dfrac{R R_1}{2R + R_1+R_2}

U_{I_\mathrm{q2}}&=-R I_\mathrm{q2}\cdot \dfrac{R_1}{R_1+R_2+R||(R_1+R_2)} \cdot \dfrac{R_1 + R_2}{R + R_1 + R_2} =-I_\mathrm{q2}\cdot \dfrac{R R_1}{2R + R_1+R_2}

\end{align*}
\[
\underline{U=\dfrac{R R_1}{2R + R_1+R_2}\left(I_\mathrm{q1}-I_\mathrm{q2}\right)}
\]
